CREATE OR REPLACE FUNCTION private.d11b_preview_soak_scheduler_tick()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'vault', 'net', 'cron'
AS $function$
declare
  v_token text;
  v_request_id bigint;
  v_ends timestamptz;
begin
  perform pg_advisory_xact_lock(
    hashtext('wakilisha-d11b-preview-soak-db-clock')
  );

  select ends_at_utc
  into v_ends
  from private.d11b_preview_soak_scheduler_control
  where control_id
  for update;

  if v_ends is null then
    raise exception 'D11B Preview scheduler control row is missing.';
  end if;

  if clock_timestamp() > v_ends then
    update private.d11b_preview_soak_scheduler_control
    set
      state='closed',
      closed_at_utc=coalesce(closed_at_utc,clock_timestamp()),
      updated_at_utc=clock_timestamp()
    where control_id;

    begin
      perform cron.unschedule('wakilisha-d11b-preview-soak-db-clock');
    exception
      when others then null;
    end;

    return null;
  end if;

  select decrypted_secret
  into v_token
  from vault.decrypted_secrets
  where name='d11b_preview_soak_scheduler_token'
  order by created_at desc
  limit 1;

  if nullif(v_token,'') is null then
    raise exception 'D11B Preview scheduler token is missing.';
  end if;

  select net.http_post(
    url:='https://irgtqkcrufvldrznqcuv.supabase.co/functions/v1/d11b-preview-soak-tick',
    body:='{}'::jsonb,
    headers:=jsonb_build_object(
      'content-type','application/json',
      'x-wk-scheduler-token',v_token
    ),
    timeout_milliseconds:=10000
  )
  into v_request_id;

  update private.d11b_preview_soak_scheduler_control
  set
    last_request_id=v_request_id,
    last_invoked_at_utc=clock_timestamp(),
    updated_at_utc=clock_timestamp()
  where control_id;

  return v_request_id;
end
$function$

CREATE OR REPLACE FUNCTION public.install_d11b_preview_soak_scheduler_v1(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'vault', 'cron'
AS $function$
declare
  v_secret_id uuid;
  v_job_id bigint;
begin
  if session_user<>'authenticator'
     or current_user<>'postgres'
  then
    raise exception using errcode='42501',
      message='D11B Preview scheduler installer requires Data API service-role transport.';
  end if;

  if length(coalesce(p_token,''))<32 then
    raise exception using errcode='22023',
      message='D11B Preview scheduler token is too short.';
  end if;

  select id
  into v_secret_id
  from vault.secrets
  where name='d11b_preview_soak_scheduler_token'
  order by created_at desc
  limit 1;

  if v_secret_id is null then
    v_secret_id:=vault.create_secret(
      p_token,
      'd11b_preview_soak_scheduler_token',
      'Preview-only D11B database scheduler bridge token',
      null
    );
  else
    perform vault.update_secret(
      v_secret_id,
      p_token,
      'd11b_preview_soak_scheduler_token',
      'Preview-only D11B database scheduler bridge token',
      null
    );
  end if;

  begin
    perform cron.unschedule('wakilisha-d11b-preview-soak-db-clock');
  exception
    when others then null;
  end;

  select cron.schedule(
    'wakilisha-d11b-preview-soak-db-clock',
    '*/5 * * * *',
    'select private.d11b_preview_soak_scheduler_tick();'
  )
  into v_job_id;

  update private.d11b_preview_soak_scheduler_control
  set
    state='running',
    starts_at_utc=coalesce(starts_at_utc,clock_timestamp()),
    cron_job_id=v_job_id,
    updated_at_utc=clock_timestamp(),
    closed_at_utc=null
  where control_id;

  return jsonb_build_object(
    'installed',true,
    'cron_job_id',v_job_id,
    'window_id','a759d574-aa1c-4037-92b9-abc929a89e0c',
    'ends_at_utc','2026-10-12T18:35:00Z'
  );
end
$function$
